-- BoiForte: rastreabilidade (PNIB, GTA, CAR, ITR) e geolocalização da fazenda para a exportação à União Europeia (EUDR).
--
-- O que esta migração faz:
--   1. Fazenda (propriedades) ganha: nome do produtor, ponto da sede (lat/lon), contorno da divisa
--      (lista de até 2.000 pontos lat/lon), declaração "sem desmatamento depois de 31/12/2020",
--      recibo e situação do CAR, CIB/NIRF e ano do último ITR, CCIR e ano, código do estabelecimento
--      no órgão de defesa e inscrição estadual. Sem esta migração o servidor DESCARTA esses campos.
--   2. Tabela nova "gtas" (Guia de Trânsito Animal: entrada ou saída de animais), ligada à fazenda e,
--      se quiser, a um lote da MESMA fazenda (o servidor confere a referência, como nas outras tabelas).
--   3. Permissões: o vaqueiro VÊ as GTAs (não há dinheiro nelas), mas não lança nem apaga
--      (gtas não entra em bf_vaqueiro_grava). Consultor só vê, como em tudo. Dono e gerente lançam.
--      Os documentos da fazenda seguem a regra de "propriedades": o vaqueiro não muda.
--   4. Gatilho no servidor: GTA precisa ter pelo menos 1 animal (machos + fêmeas > 0) e o lote,
--      quando informado, tem de ser da mesma fazenda da GTA (propriedadeId do lote = propriedadeId da GTA).
--
-- Depende de 20261124150000 (pasto) e das anteriores. Rode ANTES de publicar a versão do app com Rastreabilidade.

-- ---------------------------------------------------------------- 3. vaqueiro vê as GTAs
create or replace function public.bf_vaqueiro_le() returns text[] language sql immutable as $$
  select array['propriedades','modulos','piquetes','lotes','animais','pesagens','ingredientes','formulas','movimentos','batidas','fornecimentos','sanidade','lembretes','config','anotacoes','ocupacoes','ndvi','gtas']
$$;

-- ---------------------------------------------------------------- 4. conferências da GTA no servidor
create or replace function public.bf_gtas_antes_gravar() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  lote_prop text;
  prop_gta text;
begin
  if new.excluido or new.dados is null then return new; end if;
  if coalesce((new.dados->>'machos')::numeric, 0) + coalesce((new.dados->>'femeas')::numeric, 0) <= 0 then
    perform public.bf_erro('GTA: informe quantos animais ela leva.');
  end if;
  -- Lote informado: precisa ser da mesma fazenda (propriedade) da GTA. Os ids no servidor são os gid.
  if new.dados ? 'loteId' and new.dados->>'loteId' is not null then
    select r.dados->>'propriedadeId' into lote_prop from public.registros r
      where r.fazenda_id = new.fazenda_id and r.tabela = 'lotes' and r.gid = new.dados->>'loteId' and not r.excluido;
    prop_gta := new.dados->>'propriedadeId';
    if lote_prop is not null and lote_prop is distinct from prop_gta then
      perform public.bf_erro('GTA: o lote é de outra fazenda.');
    end if;
  end if;
  return new;
end $$;

drop trigger if exists registros_gtas on public.registros;
create trigger registros_gtas before insert or update on public.registros
  for each row when (new.tabela = 'gtas') execute function public.bf_gtas_antes_gravar();

revoke execute on function public.bf_gtas_antes_gravar() from public, anon, authenticated;
grant execute on function public.bf_vaqueiro_le() to authenticated;

